package docker

import("context";"encoding/json";"errors";"fmt";"os";"os/exec";"path/filepath";"runtime";"strconv";"strings";"github.com/example-user/runnerhub/internal/core";"github.com/example-user/runnerhub/internal/hostinfo";"github.com/example-user/runnerhub/internal/provider")
type CommandRunner interface{Run(context.Context,string,...string)(string,error)};type execRunner struct{}
func(execRunner)Run(ctx context.Context,name string,args ...string)(string,error){b,err:=exec.CommandContext(ctx,name,args...).CombinedOutput();if err!=nil{return string(b),fmt.Errorf("%s: %w: %s",name,err,sanitize(string(b)))};return string(b),nil}
type Config struct{DockerBinary string;StateDir string;AllowedImages []string;HostID string;DefaultWorkdirBytes int64};type Provider struct{cfg Config;run CommandRunner;allowed map[string]struct{}}
func New(cfg Config)(*Provider,error){return newWithRunner(cfg,execRunner{})}
func newWithRunner(cfg Config,r CommandRunner)(*Provider,error){if cfg.DockerBinary==""{cfg.DockerBinary="docker"};if cfg.StateDir==""{cfg.StateDir="/var/lib/runnerhub"};if cfg.DefaultWorkdirBytes<=0{cfg.DefaultWorkdirBytes=20<<30};if len(cfg.AllowedImages)==0{cfg.AllowedImages=[]string{"ghcr.io/actions/actions-runner:latest"}};a:=map[string]struct{}{};for _,i:=range cfg.AllowedImages{a[i]=struct{}{}};return &Provider{cfg:cfg,run:r,allowed:a},nil}
func(p *Provider)Capabilities(ctx context.Context)(provider.Capabilities,error){if _,err:=p.run.Run(ctx,p.cfg.DockerBinary,"version","--format","{{.Server.Version}}");err!=nil{return provider.Capabilities{},err};return provider.Capabilities{Provider:"docker",OS:runtime.GOOS,Architecture:runtime.GOARCH,Capacity:hostinfo.Capacity(p.cfg.StateDir),IsolationModes:[]core.IsolationMode{core.IsolationContainerTrusted},Features:map[string]bool{"ephemeral":true,"publishedPorts":false,"dockerSocket":false},Labels:map[string]string{"isolation.container-trusted":"true"}},nil}
func(p *Provider)Validate(_ context.Context,s provider.WorkerSpec)error{if strings.TrimSpace(s.WorkerID)==""||strings.TrimSpace(s.PoolID)==""||strings.TrimSpace(s.RunnerName)==""||s.JITConfig==""{return errors.New("worker id, pool id, runner name and jit config are required")};if s.Isolation!=core.IsolationContainerTrusted{return fmt.Errorf("docker provider only supports %s",core.IsolationContainerTrusted)};if _,ok:=p.allowed[s.Image];!ok{return fmt.Errorf("image %q is not allowlisted",s.Image)};if !core.NonNegative(s.Resources){return errors.New("resource requests cannot be negative")};return nil}
func(p *Provider)Create(ctx context.Context,s provider.WorkerSpec)(provider.WorkerHandle,error){if s.Image==""{s.Image="ghcr.io/actions/actions-runner:latest"};if err:=p.Validate(ctx,s);err!=nil{return provider.WorkerHandle{},err};secretDir:=filepath.Join(p.cfg.StateDir,"workers",safeID(s.WorkerID));if err:=os.MkdirAll(secretDir,0700);err!=nil{return provider.WorkerHandle{},err};jitPath:=filepath.Join(secretDir,"jitconfig");if err:=os.WriteFile(jitPath,[]byte(s.JITConfig),0600);err!=nil{return provider.WorkerHandle{},err};name:="runnerhub-"+safeID(s.WorkerID);args:=[]string{"run","-d","--name",name,"--label","io.runnerhub.worker="+s.WorkerID,"--label","io.runnerhub.pool="+s.PoolID,"--security-opt","no-new-privileges","--mount","type=bind,src="+jitPath+",dst=/run/runnerhub/jitconfig,readonly"};if s.Resources.CPUMillis>0{args=append(args,"--cpus",strconv.FormatFloat(float64(s.Resources.CPUMillis)/1000,'f',3,64))};if s.Resources.MemoryBytes>0{args=append(args,"--memory",strconv.FormatInt(s.Resources.MemoryBytes,10))};size:=s.Resources.DiskBytes;if size<=0{size=p.cfg.DefaultWorkdirBytes};args=append(args,"--tmpfs","/home/runner/_work:rw,exec,nosuid,nodev,size="+strconv.FormatInt(size,10),s.Image,"/bin/bash","-lc",`exec /home/runner/run.sh --jitconfig "$(cat /run/runnerhub/jitconfig)"`);out,err:=p.run.Run(ctx,p.cfg.DockerBinary,args...);if err!=nil{if id,findErr:=p.findExisting(ctx,s.WorkerID);findErr==nil&&id!=""{return provider.WorkerHandle{ProviderID:id,HostID:p.cfg.HostID},nil};_=os.RemoveAll(secretDir);return provider.WorkerHandle{},err};id:=strings.TrimSpace(out);if id==""{_=os.RemoveAll(secretDir);return provider.WorkerHandle{},errors.New("docker returned empty container id")};return provider.WorkerHandle{ProviderID:id,HostID:p.cfg.HostID},nil}
func(p *Provider)findExisting(ctx context.Context,workerID string)(string,error){out,err:=p.run.Run(ctx,p.cfg.DockerBinary,"ps","-a","--filter","label=io.runnerhub.worker="+workerID,"--format","{{.ID}}");if err!=nil{return "",err};ids:=strings.Fields(out);switch len(ids){case 0:return "",nil;case 1:return ids[0],nil;default:return "",fmt.Errorf("multiple containers claim worker %q",workerID)}}
func(p *Provider)Inspect(ctx context.Context,h provider.WorkerHandle)(provider.WorkerState,error){if strings.TrimSpace(h.ProviderID)==""{return provider.WorkerState{},errors.New("container id required")};out,err:=p.run.Run(ctx,p.cfg.DockerBinary,"inspect",h.ProviderID,"--format","{{json .State}}");if err!=nil{if strings.Contains(strings.ToLower(err.Error()),"no such"){return provider.WorkerState{State:core.WorkerDeleted,SafeDetail:"container absent"},nil};return provider.WorkerState{},err};var st struct{Running bool `json:"Running"`;ExitCode int `json:"ExitCode"`;Status string `json:"Status"`};if err:=json.Unmarshal([]byte(strings.TrimSpace(out)),&st);err!=nil{return provider.WorkerState{},err};if st.Running{return provider.WorkerState{State:core.WorkerReady,SafeDetail:"container running"},nil};code:=st.ExitCode;if st.Status=="exited"&&st.ExitCode==0{return provider.WorkerState{State:core.WorkerCompleted,ExitCode:&code,SafeDetail:"container exited successfully"},nil};return provider.WorkerState{State:core.WorkerFailed,ExitCode:&code,SafeDetail:"container exited"},nil}
func(p *Provider)Stop(ctx context.Context,h provider.WorkerHandle)error{if h.ProviderID==""{return nil};_,err:=p.run.Run(ctx,p.cfg.DockerBinary,"stop","--time","10",h.ProviderID);if err!=nil&&strings.Contains(strings.ToLower(err.Error()),"no such"){return nil};return err}
func(p *Provider)Delete(ctx context.Context,h provider.WorkerHandle)error{workerID:="";if h.ProviderID!=""{if out,err:=p.run.Run(ctx,p.cfg.DockerBinary,"inspect",h.ProviderID,"--format",`{{index .Config.Labels "io.runnerhub.worker"}}`);err==nil{workerID=strings.TrimSpace(out)};_,err:=p.run.Run(ctx,p.cfg.DockerBinary,"rm","-f",h.ProviderID);if err!=nil&&!strings.Contains(strings.ToLower(err.Error()),"no such"){return err}};if workerID!=""{_=os.RemoveAll(filepath.Join(p.cfg.StateDir,"workers",safeID(workerID)))};return nil}
func safeID(s string)string{var b strings.Builder;for _,r:=range strings.ToLower(s){if(r>='a'&&r<='z')||(r>='0'&&r<='9')||r=='-'{b.WriteRune(r)}};v:=strings.Trim(b.String(),"-");if len(v)>48{v=v[:48]};if v==""{v="worker"};return v}
func sanitize(s string)string{if len(s)>512{s=s[:512]};return strings.ReplaceAll(s,"\n"," ")}
